code.cpp:
class Solution {
public:
    int maxProduct(vector<string>& words) {
        int n = words.size();
        vector<int> masks(n, 0);
        for (int i = 0; i < n; i++) {
            for (char c : words[i]) {
                masks[i] |= (1 << (c - 'a'));
            }
        }
        int maxProd = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if ((masks[i] & masks[j]) == 0) {
                    int prod = (int)words[i].size() * (int)words[j].size();
                    maxProd = max(maxProd, prod);
                }
            }
        }
        return maxProd;
    }
};
